def _fit(X, y, it=30):
    X = np.column_stack([np.ones(len(y)), X]) if X.size else np.ones((len(y), 1))
    b = np.zeros(X.shape[1])
    for _ in range(it):
        p = 1 / (1 + np.exp(-np.clip(X @ b, -30, 30)))
        w = p * (1 - p) + 1e-9
        H = X.T @ (X * w[:, None]) + 1e-6 * np.eye(X.shape[1])
        step = np.linalg.solve(H, X.T @ (y - p))
        b += step
        if np.abs(step).max() < 1e-7:
            break
    p = np.clip(1 / (1 + np.exp(-np.clip(X @ b, -30, 30))), 1e-12, 1 - 1e-12)
    return float(np.sum(y * np.log(p) + (1 - y) * np.log(1 - p)))

def design(feats):
    x, y, ids = np.asarray(feats.x, float), np.asarray(feats.y, float), list(feats.ids)
    n, p = x.shape
    S = sorted(set(feats.stratum))
    Z = np.column_stack([[s == t for s in feats.stratum] for t in S[1:]]).astype(float) if len(S) > 1 else np.zeros((n, 0))
    R = np.corrcoef(x.T)
    def ll(cols, extra=None):
        M = [Z] + [x[:, cols]] + ([extra] if extra is not None else [])
        return _fit(np.column_stack(M), y)
    sel = []
    base = ll([])
    while len(sel) < MAX_DRIVERS:
        alpha = (0.1 if not sel else 0.05) / p
        best, bj = -1, None
        for j in range(p):
            if j in sel or any(abs(R[j, k]) >= 0.6 for k in sel):
                continue
            g = ll(sel + [j]) - base
            if g > best:
                best, bj = g, j
        if bj is None or stats.chi2.sf(2 * best, 1) > alpha:
            break
        clus = [k for k in range(p) if abs(R[bj, k]) >= 0.6 and k not in sel] or [bj]
        if len(clus) > 1:
            lls = {k: ll(sel + [k]) for k in clus}
            top = max(lls.values())
            cand = [k for k in clus if lls[k] >= top - 2]
            def cost(k):
                return sum(max(ll(sel + [k, m]) - lls[k], 0) for m in clus if m != k)
            bj = min(cand, key=cost)
        sel.append(bj)
        base = ll(sel)
    changed = True
    while changed and len(sel) > 1:
        changed = False
        full = ll(sel)
        for j in list(sel):
            rest = [k for k in sel if k != j]
            if stats.chi2.sf(2 * (full - ll(rest)), 1) > 0.05 / p:
                sel = rest; changed = True; break
    m = p * (p + 1) / 2
    sc = []
    for a in range(p):
        for b in range(a, p):
            pr = x[:, a] * x[:, b]
            pr = (pr - pr.mean()) / (pr.std() + 1e-12)
            sc.append((abs(np.corrcoef(pr, y)[0, 1]), a, b))
    sc.sort(reverse=True)
    prods = []
    for _, a, b in sc[:15]:
        mains = sorted(set(sel) | {a, b})
        pr = x[:, a] * x[:, b]
        g = ll(mains, pr) - ll(mains)
        if stats.chi2.sf(2 * g, 1) < 0.002 / m and not any({a, b} & set(q) for q in prods):
            prods.append((a, b))
        if len(prods) >= 2:
            break
    drivers = [ids[j] for j in sel]
    for a, b in prods:
        for k in (a, b):
            if ids[k] not in drivers:
                drivers.append(ids[k])
    cols = sorted(set(sel) | {k for q in prods for k in q})
    return Design(drivers=tuple(drivers[:MAX_DRIVERS]), columns=tuple(ids[k] for k in cols),
                  products=tuple((ids[a], ids[b]) for a, b in prods), loadings={})

